    # Function to find the Greatest Common Divisor (GCD) of two numbers
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    # Function to find the GCD of an array of numbers
    def find_gcd_of_array(arr):
        current_gcd = arr[0]
        for num in arr[1:]:
            current_gcd = gcd(current_gcd, num)
            if current_gcd == 1:
                break
        return current_gcd

    # Find the GCD of the entire array
    result = find_gcd_of_array(arr)

    # If the GCD is 1, it means there is no single number that divides all elements
    if result == 1:
        return -1

